OneSampleTTest <- function(
    data,
    sm,
    pm,
    ssd,
    sn,
    a = "0.0250") {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("OneSampleTTest requires jmvcore to be installed (restart may be required)")

    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame())


    options <- OneSampleTTestOptions$new(
        sm = sm,
        pm = pm,
        ssd = ssd,
        sn = sn,
        a = a)

    analysis <- OneSampleTTestClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

